  if (state.landedFor >= TASK.landingHold && !state.reason) state.reason = 'landed';
}

export function evalController(makeController, seeds, verbose = false) {
  let passed = 0;
  const reasons = {};
  let totalTime = 0;
  for (const seed of seeds) {
    const parameters = trialParameters(seed), state = initialState(parameters), rng = random((seed ^ 0xa5a5a5a5) >>> 0);
    const controller = makeController();
    for (let step = 0; step < Math.round(TASK.duration / TASK.dt) && !state.reason; step++) {
      const rawAction = controller.step(observation(state, rng));
      const action = {
        thrust: clamp(rawAction.thrust, 0, 1),
        roll: clamp(rawAction.roll, -0.6, 0.6),
        pitch: clamp(rawAction.pitch, -0.6, 0.6),
        yawRate: clamp(rawAction.yawRate, -2, 2),
      };
      for (let sub = 0; sub < TASK.substeps && !state.reason; sub++) integrate(state, action, parameters, TASK.dt / TASK.substeps);
    }
    const reason = state.reason || 'time limit';
    if (reason === 'landed') { passed++; totalTime += state.t; }
    reasons[reason] = (reasons[reason] || 0) + 1;
    if (verbose && reason !== 'landed') {
      const err = Math.hypot(state.pos.x - PAD.centre.x, state.pos.z - PAD.centre.z).toFixed(3);
      console.log(`  seed ${seed}: ${reason} (gates=${state.gateIndex}, t=${state.t.toFixed(2)}s, pos=(${state.pos.x.toFixed(2)},${state.pos.y.toFixed(2)},${state.pos.z.toFixed(2)}), padErr=${err})`);
    }
  }
  console.log(`Passed: ${passed}/${seeds.length} (${(100*passed/seeds.length).toFixed(1)}%), avg landed t=${passed ? (totalTime/passed).toFixed(2) : 0}s`, reasons);
  return { passed, reasons };
}
